    # If we're already (or almost) as close as opponent, switch to nearest overall to secure safely.
    nearest = min(resources, key=lambda c: (man(sx, sy, c[0], c[1]), man(ox, oy, c[0], c[1]), c[0], c[1]))
    sd_best = man(sx, sy, rx, ry)
    od_best = man(ox, oy, rx, ry)
    target = (rx, ry) if (od_best - sd_best) >= 1 else nearest

    tx, ty = target

    # If target is blocked, pick best reachable step towards it; otherwise also consider opponent proximity.
    def step_score(dx, dy):
        nx, ny = sx + dx, sy + dy
        if not (0 <= nx < w and 0 <= ny < h) or (nx, ny) in obstacles:
            return -10**9
        d1 = man(nx, ny, tx, ty)
        # deter giving opponent too much progress: prefer steps that increase their distance to target
        d2 = man(ox, oy, tx, ty)
        # since opponent position doesn't change, use our move only; tie-break using our distance to opponent and obstacles not needed
        return (-(d1), (man(nx, ny, ox, oy)), -((abs(nx - tx) + abs(ny - ty)) % 2), -nx, -ny)

    best_step = (0, 0)
    best_val = -10**9
    for dx, dy in moves:
        v = step_score(dx, dy)
        if v > best_val:
            best_val = v
            best_step = (dx, dy)

    return [int(best_step[0]), int(best_step[1])]

